import{c as t,Q as s,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Creating Leaderboard screens","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/creating-screens.md","filePath":"user/screens/creating-screens.md"}'),o={name:"user/screens/creating-screens.md"};function a(i,e,l,c,d,h){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="creating-leaderboard-screens" tabindex="-1">Creating Leaderboard screens <a class="header-anchor" href="#creating-leaderboard-screens" aria-label="Permalink to &quot;Creating Leaderboard screens&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators setting up spectator-facing displays.</p><p>A <strong>screen</strong> is a live Leaderboard display you configure once and then open as a web page on a TV, laptop or tablet. Each screen has its own <strong>ID</strong>, its own set of classes, and its own layout, so you can run several at once — for example one TV showing the elite classes and another showing the juniors. Because a screen is just a web page, nothing is installed on the display device: you point its browser at the screen&#39;s URL and leave it running. See <a href="./../what-is-mesho-manager/">How meshO Manager works</a> for the one-server, many-browsers model.</p><blockquote><p>Leaderboard screens are the arena displays you build here. They&#39;re separate from the built-in <strong>Spectator</strong> and <strong>Kiosk</strong> views — the public, self-serve pages competitors open on their own phones — which need no setup. See the <a href="./../getting-started/concepts-glossary#screens-and-views">glossary</a> for the distinction.</p></blockquote><h2 id="the-screens-page" tabindex="-1">The Screens page <a class="header-anchor" href="#the-screens-page" aria-label="Permalink to &quot;The Screens page&quot;">​</a></h2><p>Open <strong>Screens</strong> from the event navigation. It has three sections:</p><ul><li><strong>Leaderboard TV Screens</strong> — a bank of TVs managed together. See <a href="./tv-screens">TV screens</a>.</li><li><strong>All Leaderboard screens</strong> — every screen in the event, in a table.</li><li><strong>Commentary</strong> — open the announcer&#39;s live feed. See <a href="./commentary">Commentary</a>.</li></ul><p>Every event has one built-in screen called <strong>all</strong>, which shows every class. It&#39;s the simplest thing to put on a single display.</p><h2 id="creating-a-screen" tabindex="-1">Creating a screen <a class="header-anchor" href="#creating-a-screen" aria-label="Permalink to &quot;Creating a screen&quot;">​</a></h2><p>In the <strong>All Leaderboard screens</strong> section, click <strong>Create New Screen</strong>, give it a <strong>Screen ID</strong>, and click <strong>Create</strong>. The ID is how you refer to the screen and it appears in the screen&#39;s URL, so keep it short and memorable (<code>elite</code>, <code>juniors</code>, <code>arena1</code>). It must be unique within the event.</p><p>A new screen inherits your global <strong>screen defaults</strong> (set on the <a href="./../reference/settings">Settings</a> page) for things like fonts and columns — you can fine-tune any of them afterwards. It starts with <strong>no classes</strong>, so the next step is to choose what it shows.</p><h2 id="choosing-which-classes-a-screen-shows" tabindex="-1">Choosing which classes a screen shows <a class="header-anchor" href="#choosing-which-classes-a-screen-shows" aria-label="Permalink to &quot;Choosing which classes a screen shows&quot;">​</a></h2><p>In the screen&#39;s row, the <strong>Classes</strong> column controls what appears:</p><ul><li>Click the <strong>expand</strong> arrow to see the classes currently on the screen as chips.</li><li>Click the <strong>+</strong> (add) button to open the <strong>Add classes</strong> dialog — search by class name (the table also shows which other screens already show each class), tick the ones you want, and <strong>Add</strong>.</li><li>Remove a class by clicking the <strong>×</strong> on its chip.</li><li>You can <strong>drag class chips between screens</strong> in the table to move them around quickly.</li></ul><p>The <strong>all</strong> screen is special — it always shows <strong>All classes</strong> and you don&#39;t manage its class list.</p><h2 id="adjusting-a-screen-s-settings" tabindex="-1">Adjusting a screen&#39;s settings <a class="header-anchor" href="#adjusting-a-screen-s-settings" aria-label="Permalink to &quot;Adjusting a screen&#39;s settings&quot;">​</a></h2><p>Click the <strong>gear</strong> icon in a screen&#39;s row to open its settings. There are two tabs.</p><p><strong>Settings</strong> — the layout and content of the display:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Columns</strong></td><td>How many class columns sit side by side (1–6). More columns fit more on a wide TV.</td><td>2</td></tr><tr><td><strong>Font Size</strong></td><td>Base text size. Larger for a TV seen from across the arena.</td><td>10</td></tr><tr><td><strong>Name Column Width</strong></td><td>Small / Medium / Large room for competitor names.</td><td>Medium</td></tr><tr><td><strong>Club Display</strong></td><td>Hide the club, or show <strong>Abbreviations</strong> or <strong>Full Names</strong>.</td><td>Hide</td></tr><tr><td><strong>Max Radios</strong></td><td>How many radio-control splits to show per course.</td><td>4</td></tr><tr><td><strong>Competitor Time Display</strong></td><td><strong>Elapsed</strong> time, <strong>Difference</strong> (behind the leader), or <strong>Both</strong>.</td><td>Both</td></tr><tr><td><strong>Max Places Per Class</strong></td><td>Show <strong>All</strong> finishers or just the top 3–10.</td><td>All</td></tr><tr><td><strong>Show Club Icon</strong></td><td>Show each club&#39;s badge.</td><td>on</td></tr><tr><td><strong>Auto-scroll</strong></td><td>Scroll long class lists automatically so everyone gets airtime.</td><td>on</td></tr><tr><td><strong>Show Header</strong></td><td>Show the logo, event name and clock at the top. Turn off to reclaim space.</td><td>on</td></tr><tr><td><strong>Show Relay Team Members on Single Line</strong></td><td>Compact relay rows.</td><td>off</td></tr><tr><td><strong>Show Projected Times…</strong></td><td>Estimate finish times for runners seen at a radio control but not yet finished.</td><td>on</td></tr><tr><td><strong>Show Start Time</strong></td><td>Show each competitor&#39;s start time.</td><td>on</td></tr><tr><td><strong>Show Class Names in Header</strong></td><td>Label each column with its class.</td><td>on</td></tr></tbody></table><p><strong>Snapshot</strong> — click <strong>Refresh Snapshot</strong> to capture a live screenshot of the screen as it currently renders. It&#39;s the quickest way to check the layout looks right without walking over to the TV. (A snapshot only works while the screen is open somewhere.)</p><p>Use <strong>Apply</strong> to save and keep tweaking, or <strong>Save</strong> to save and close.</p><h2 id="keeping-an-eye-on-a-running-screen" tabindex="-1">Keeping an eye on a running screen <a class="header-anchor" href="#keeping-an-eye-on-a-running-screen" aria-label="Permalink to &quot;Keeping an eye on a running screen&quot;">​</a></h2><p>Once a screen is open on a display, its row reports live health so you can spot a TV that&#39;s dropped off:</p><ul><li><strong>Last Heard From</strong> — when the screen last checked in. Green means it&#39;s reporting now; grey means it&#39;s gone quiet.</li><li><strong>FPS</strong> — how smoothly it&#39;s refreshing (green is healthy, orange is marginal, red is struggling). Click the number for a history graph that also marks disconnects, reconnects and reloads.</li><li><strong>DC / RL</strong> — counts of <strong>disconnections</strong> and <strong>force reloads</strong>, flagged when they happen.</li></ul><h2 id="deleting-a-screen" tabindex="-1">Deleting a screen <a class="header-anchor" href="#deleting-a-screen" aria-label="Permalink to &quot;Deleting a screen&quot;">​</a></h2><p>Open the screen&#39;s settings (gear icon) and click <strong>Delete</strong>, then confirm. The built-in <strong>all</strong> screen can&#39;t be removed.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./tv-screens">TV screens</a> — set up and drive a whole bank of arena TVs at once</li><li><a href="./commentary">Commentary</a> — the announcer&#39;s live feed</li><li><a href="./../after-the-event/results">Results</a> — the operator-facing results and exports</li></ul>',28)])])}const u=t(o,[["render",a]]);export{p as __pageData,u as default};
